addModificationValue: function(object, name) {
const $object=$(object);
const type=$object.attr('type');
let value=null;
switch(type) {
case 'checkbox':
value=+$object.is(':checked');
break;
case 'text':
value=$object.val();
break;
}
if($.cookie(name) !== null) {
$.cookie(name, value);
}else {
$.cookie(name, value, { expires: 365 }); // days
}
},
