$(function() {
$('body')
.on(
{
'click': function() {
var $this=$(this);
$this.focus();
if($this.hasClass('blocked')||$this.parent('.not-changeable').length)
{
return false;
}
var $input=$this.closest('.dms-document-icons-permissions').find('input[type=hidden]'),
val=$input.val(),
bitmask=$this.data('bitmask');
switch($this.data('bitoperation'))
{
case 'xor':
val ^= bitmask;
break;
case 'or':
val |= bitmask;
break;
case 'and':
val &= bitmask;
break;
}
$input.val(val);
var isSet=$this.hasClass('set-permissions'),
isRemove=$this.hasClass('remove-permissions');
if(!isSet&&!isRemove)
{
$this.toggleClass('fa-solid fa-regular');
}
if(isSet||isRemove)
{
var $aI=$this.closest('.dms-document-icons-permissions').find('i:not(.set-permissions):not(.remove-permissions)');
if(isSet) {
$aI.removeClass('fa-regular').addClass('fa-solid');
}else {
$aI.removeClass('fa-solid').addClass('fa-regular');
}
}
}
},
'.dms-document-icons-permissions i'
)
.on(
{
'click': function() {
var $this=$(this);
$this.focus();
if($this.hasClass('blocked')||$this.parent('.not-changeable').length)
{
return false;
}
var type=$this.data('type'),
objectId=$this.data('id'),
dmsDocumentTypeId=$this.data('dms-document-type-id'),
dmsClassId=$this.data('dms-class-id'),
action=$this.data('action-id');
$.adminLoad({
path: hostcmsBackend+'/dms/document/type/index.php',
action: 'changeAccess',
operation: '',
additionalParams: 'dms_class_id='+dmsClassId+'&dms_document_type_id='+dmsDocumentTypeId+'&type='+type+'&objectId='+objectId+'&action='+action+'&hostcms[checked][0]['+dmsDocumentTypeId+']=1',
windowId: 'id_content'
});
},
'mousedown': function() {
$(this).removeClass('changed');
},
'mouseover': function() {
var $this=$(this);
if($this.hasClass('changed'))
{
$this.toggleClass('fa-solid fa-regular');
}
},
'mouseout': function() {
$(this).removeClass('changed');
}
},
'.dms-document-type-icons-permissions i'
);
});
